settings.liquid_Metafiled_accordion:
{%- if product.metafields.my_fields.how_to_use_video != blank or product.metafields.my_fields.how_to_use_description != blank -%}
<div class="howToUseFaqContent">
  {%- if product.metafields.my_fields.how_to_use_video != blank %}
   {% assign video_id = product.metafields.my_fields.how_to_use_video | split : 'vimeo.com/' | last %}
  <iframe src="//player.vimeo.com/video/{{ video_id }}?byline=0&portrait=0&badge=0" frameborder="0" webkitallowfullscreen mozallowfullscreen allowfullscreen></iframe>
  {% endif %}
  <p>{{ product.metafields.my_fields.how_to_use_description }}</p>
</div>
{%- endif -%}
